INSERT INTO "Feature" ("id", "productId", "content") VALUES ('d64f7f4d-ad3d-410c-9222-cd8350df17c5', 'f05c606b-6061-4a9d-b059-474b5d1b2f89', 'ছাদের ওপর বসে থাকা একাকী চরিত্র আর নরম সন্ধ্যার রঙ মিলিয়ে তৈরি হয়েছে এক বিষণ্ণ ভিজ্যুয়াল, যা বিচ্ছেদ, অপেক্ষা আর না বলা ভালোবাসার গল্প মনে করিয়ে দেয়');
