INSERT INTO "Feature" ("id", "productId", "content") VALUES ('18acfe45-8d0a-4068-93b0-e9b9e8a244c7', '8fb65110-ccc3-48a7-b0a8-1270d53ca7f0', '“অরুণ প্রাতের তরুণ দল” লেখাটি শক্তিশালী ও সাহসী বাংলা টাইপোগ্রাফিতে উপস্থাপন করা হয়েছে, যেখানে ভোরের নতুন সূচনা ও তরুণদের উদ্যমী মানসিকতা একসাথে ফুটে উঠেছে।');
INSERT INTO "Feature" ("id", "productId", "content") VALUES ('47c0b33d-621d-44d3-b1cf-c26e24c6260a', '8fb65110-ccc3-48a7-b0a8-1270d53ca7f0', 'সাদা ও সোনালি রঙের কনট্রাস্ট ব্যবহার করে ডিজাইনটি আশাবাদ, আত্মবিশ্বাস ও পরিবর্তনের প্রতীক হিসেবে দাঁড়ায়, যা তরুণ প্রজন্মের চিন্তা ও স্বপ্নকে ভিজ্যুয়ালি প্রকাশ করে।');
INSERT INTO "Feature" ("id", "productId", "content") VALUES ('fef58376-9530-415f-9cf7-abf25782d394', '4abcc4e9-e67e-49fb-914c-4d65be07eb0f', '“আমি বদলে যাব” কথাটি বড় ও আত্মবিশ্বাসী বাংলা টাইপোগ্রাফিতে উপস্থাপন করা হয়েছে, যা ব্যক্তিগত পরিবর্তন, আত্মউন্নয়ন ও নতুন শুরুর দৃঢ় সংকল্পকে শক্তভাবে ভিজ্যুয়ালি প্রকাশ করে।');
