INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('3c270ecf-6393-4ccd-9c52-0a2777f51be2', 'Keep It Classic | Vintage Vinyl Record Retro Music T-Shirt', '“Keep It Classic” is a tribute to the golden era of music—when vinyl ruled, albums had soul, and every track told a story. This design captures the charm of analog sound and the timeless appeal of records that never go out of style.
