INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('c9f869fe-5e94-40c6-a22c-ad93348229ee', 'Breaking the Wall – Power Shot Football Minimal Design T-Shirt', 'Breaking the Wall is a powerful minimal football design that captures the exact moment when strength meets impact. The cracked surface exploding around the ball represents determination, pressure, and the unstoppable drive to win. With sharp lines, controlled negative space, and dramatic fracture details, the design visually communicates power without needing words. It reflects the mindset of players and fans who believe nothing can stand in the way of passion and hard work. This design is perfect for those who live football with intensity, confidence, and an unbreakable spirit.', 990, 'Wed Feb 04 2026 21:44:44 GMT+0600 (Bangladesh Standard Time)', 'Thu Feb 05 2026 01:30:01 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/breaking-the-wall-power-shot-football-minimal-design-t-shirt/1770241483572-04.02.2026-17.png', 'breaking-the-wall-power-shot-football-minimal-design-t-shirt', 'ACTIVE');
