INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('c728e5e5-ceaa-48e4-97a6-e3197c5969fb', 'Well Done is Better Than Well Said – Motivational Gym Design T-Shirt', 'This motivational gym quote design emphasizes the belief that action matters more than words. Featuring bold lettering with barbell and dumbbell graphics, it reflects dedication, discipline, and hard work in fitness and training. Perfect for those who believe real results come from effort, not excuses.', 995, 'Mon Jan 19 2026 19:55:49 GMT+0600 (Bangladesh Standard Time)', 'Mon Jan 19 2026 19:55:59 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'GYM Motivation Apparel.', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', 'b21c0bc4-4d74-4403-a1ad-eb1d242bf4da', true, true, NULL, 'designs/well-done-is-better-than-well-said-motivational-gym-design-t-shirt/1768852548061-019.png', 'well-done-is-better-than-well-said-motivational-gym-design-t-shirt', 'ACTIVE');
