INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('b65e43a4-f113-4630-96ce-7db06337c7c1', 'এই রাত তোমার আমার – বাংলা টাইপোগ্রাফি T-Shirt', 'এই টি-শার্টটি সম্পর্কের নরম মুহূর্ত আর রাতের গভীর অনুভূতিকে তুলে ধরে। “এই রাত তোমার আমার” কথাটি একসাথে থাকা, চুপচাপ সময় কাটানো আর বোঝাপড়ার উষ্ণতাকে প্রকাশ করে। নিচে থাকা বাতির আলো আর অন্ধকারের কনট্রাস্ট পুরো ডিজাইনটিকে করেছে শান্ত, রোমান্টিক এবং আবেগঘন।
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('fa831c98-7954-41a0-8005-03514302a09a', 'Vintage 1980 – 1980 Birthday T-Shirt', '“Vintage 1980” is a tribute to an iconic decade that shaped pop culture, creativity, and attitude. The large numerals stand confidently at the center, while the horizontal stripes and muted retro palette recall old-school posters, vinyl covers, and classic signage.
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('943cc673-6aea-4220-93f7-dc58309b9b9f', 'Trewrrwerw T-Shirt', '', 995, 'Thu Mar 26 2026 14:56:14 GMT+0600 (Bangladesh Standard Time)', 'Fri Apr 10 2026 16:29:51 GMT+0600 (Bangladesh Standard Time)', 6, 'd4b6f556-9bfe-4d11-a619-5a3964d9ff03', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', 'eefaea0b-db67-4e8a-9a96-21660262292b', true, true, NULL, 'designs/trewrrwerw-t-shirt/1774536973610-front-design-94c275da-b6e5-4a08-a723-60179bb513d5-1.png', 'trewrrwerw-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('3d8f79c0-cc7f-4102-8850-783c77adcb9f', 'এক কাপ চায়ে আমি তোমাকে চাই – বাংলা টাইপোগ্রাফি T-Shirt', 'এই টি-শার্টটি চায়ের কাপে জমে থাকা আবেগের গল্প বলে। “এক কাপ চায়ে আমি তোমাকে চাই” কথাটি খুব সাধারণ হলেও ভেতরে লুকিয়ে আছে ভালোবাসা, টান আর কাছে থাকার ইচ্ছা। ধোঁয়া ওঠা চায়ের কাপের সাথে সাদা বাংলা লেখাটি পুরো ডিজাইনকে করেছে উষ্ণ, নরম আর হৃদয়ছোঁয়া।
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('eba8636e-d10f-45b7-8d11-3b590107d6c0', 'একা বেঁচে থাকতে শেখা প্রিয় – বাংলা অনুভূতির টাইপোগ্রাফি T-Shirt', 'এই টি-শার্টটি একাকিত্বকে দুর্বলতা নয়, বরং শক্তি হিসেবে দেখার গল্প বলে। “একা বেঁচে থাকতে শেখা প্রিয়” কথাটির ভেতরে আছে বাস্তবতা, আত্মসম্মান আর নিজের সাথে মানিয়ে নেওয়ার সাহস। চাঁদের আলোয় দাঁড়িয়ে থাকা একাকী অবয়ব পুরো ডিজাইনকে করেছে নীরব, গভীর এবং চিন্তাশীল।
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('5d7219b2-f54f-4b5a-9730-a15a6daa5a4f', 'এখনো হাত ধরা বাকি – বাংলা ভালোবাসার টাইপোগ্রাফি T-Shirt', 'এই টি-শার্টটি অপূর্ণ থাকা ভালোবাসার সুন্দর প্রতিশ্রুতি বহন করে। “এখনো হাত ধরা বাকি” কথাটির ভেতরে আছে একসাথে পথ চলার আশা, ভবিষ্যতের স্বপ্ন আর নীরব ভালোবাসার টান। সূর্যাস্তের আলোয় গাড়ির ছাদে পাশাপাশি বসে থাকা যুগলের দৃশ্য পুরো ডিজাইনকে করেছে উষ্ণ, শান্ত আর আবেগঘন।
