INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('421fc632-9619-43f3-ae6a-1d5cc356b0f2', 'অমর একুশে – ২১শে ফেব্রুয়ারি আন্তর্জাতিক মাতৃভাষা দিবস T-Shirt', 'এই “অমর একুশে” ডিজাইনটি ভাষা আন্দোলনের আত্মত্যাগ ও গৌরবময় ইতিহাসকে স্মরণ করে তৈরি। শক্তিশালী লেখনী ও প্রতীকী ভিজ্যুয়াল একুশের চেতনা, মাতৃভাষার প্রতি ভালোবাসা এবং বাঙালির আত্মপরিচয়কে গভীরভাবে প্রকাশ করে। এটি কেবল একটি ডিজাইন নয়, বরং একটি ইতিহাস ও অনুভূতির প্রতিনিধিত্ব।', 990, 'Wed Jan 21 2026 20:18:44 GMT+0600 (Bangladesh Standard Time)', 'Wed Jan 21 2026 21:40:42 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Days', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-30/1769026723015---.png', 't-shirt-30', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('99963302-2178-4a05-9ca7-419fb26db39a', 'অমর একুশে ফেব্রুয়ারি – একুশ আমার গর্ব, একুশ আমার অহংকার T-Shirt', 'এই ডিজাইনটি অমর একুশে ফেব্রুয়ারির আত্মত্যাগ ও ভাষা আন্দোলনের গৌরবকে সম্মান জানিয়ে তৈরি। শহীদ মিনারের প্রতীক, লাল রঙের সূর্য এবং উড়ন্ত পাখির সংযোজনে এটি স্বাধীনতা, আত্মপরিচয় ও জাতীয় গর্বের গভীর বার্তা বহন করে। “একুশ আমার গর্ব, একুশ আমার অহংকার” লেখাটি বাংলা ভাষা ও সংস্কৃতির প্রতি ভালোবাসার দৃঢ় প্রকাশ, যা এই ডিজাইনকে আবেগী ও ঐতিহাসিক গুরুত্বে সমৃদ্ধ করেছে।', 990, 'Wed Jan 21 2026 20:39:05 GMT+0600 (Bangladesh Standard Time)', 'Wed Jan 21 2026 21:40:57 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Days', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-32/1769027943518----.png', 't-shirt-32', 'ACTIVE');
