INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('bffc3957-ad44-405d-aa52-b4c7fe268228', 'A Mind Full of Stories Artistic Book Lover Illustration T-Shirt', 'This artistic illustration represents a mind shaped by stories, knowledge, and imagination. The design blends human identity with a library of books, symbolizing learning, creativity, and inner growth. Created for book lovers, readers, writers, and deep thinkers, this design celebrates the power of reading and the worlds we carry inside our minds.', 995, 'Thu Jan 22 2026 20:47:20 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 23 2026 15:48:22 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'MindInk Studio', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', 'b21c0bc4-4d74-4403-a1ad-eb1d242bf4da', true, true, NULL, 'designs/a-mind-full-of-stories-artistic-book-lover-illustration-t-shirt/1769114839984-01.png', 'a-mind-full-of-stories-artistic-book-lover-illustration-t-shirt', 'ACTIVE');
