INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('41d81bb9-f767-4846-a677-d5ae56c8e0f0', 'এই বিলাই চল পালাই… | Cat Mom Bangla T-Shirt', 'এই ডিজাইনটি পুরোপুরি ফানি ও কিউট ভাবনার উপর তৈরি। স্কুটারে চলা চরিত্রের সঙ্গে একটি বিড়াল যোগ করে “এই বিলাই চল পালাই…” লেখাটি মজার পরিস্থিতির ইঙ্গিত দেয়। নরম রঙ, কার্টুন ভিজ্যুয়াল ও গোল টাইপোগ্রাফি একসাথে ডিজাইনটিকে হালকা, হাস্যরসপূর্ণ ও আনন্দদায়ক একটি গল্পের মতো উপস্থাপন করেছে।', 990, 'Wed Jan 21 2026 22:00:09 GMT+0600 (Bangladesh Standard Time)', 'Thu Jan 22 2026 00:52:48 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Kitty', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/cat-mom-bangla-t-shirt/1769032807161-----.png', 'cat-mom-bangla-t-shirt', 'ACTIVE');
