INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('130c388a-8efe-46fd-bbe8-f2c0a9b5065e', 'Stay Positive – Minimal Motivation Typography T-Shirt', '“Stay Positive” is a visual reminder to focus on hope, clarity, and inner strength even when circumstances feel heavy. The smooth handwritten script contrasts with the strong outlined typography, symbolizing the balance between emotion and resilience.
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('8bb674ea-b370-4b26-a22b-9dd9a0359249', 'এমন যদি হতো আমি পাখির মতো | স্বপ্নময় বাংলা টাইপোগ্রাফি T-Shirt', '“এমন যদি হতো আমি পাখির মতো”—এই কথাটার ভেতরে লুকিয়ে আছে মানুষের চিরন্তন স্বাধীনতার স্বপ্ন। এই ডিজাইনটি সেই অনুভূতিকে দৃশ্যমান করে, যেখানে মন চায় সব বাধা পেরিয়ে খোলা আকাশে উড়ে যেতে। গভীর, ডার্ক টোনে তৈরি বাংলা টাইপোগ্রাফি শব্দগুলোকে আরও অনুভবযোগ্য করে তোলে এবং একধরনের নীরব আবেগ তৈরি করে। পুরো কম্পোজিশনটি এমনভাবে সাজানো, যেন প্রতিটি অক্ষর নিজেই একেকটি অনুভূতির স্তর। এটি কেবল একটি লেখা নয়, বরং স্বপ্ন, মুক্তি আর কল্পনার গল্প—যা নিঃশব্দে মনের কথা বলে যায়।', 990, 'Thu Jan 22 2026 09:57:41 GMT+0600 (Bangladesh Standard Time)', 'Thu Jan 22 2026 14:54:59 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Typewriter', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-39/1769075860469-------.png', 't-shirt-39', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('a024abcd-5ac2-4783-9b25-e9de53ce0395', 'এলাকার নেতা | ফানি বাংলা টাইপোগ্রাফি T-Shirt', '“এলাকার নেতা” ডিজাইনটি তৈরি করা হয়েছে লোকাল সুয়াগ, মজা আর আত্মবিশ্বাসকে একসাথে তুলে ধরার জন্য। বোল্ড ও ক্লিয়ার বাংলা টাইপোগ্রাফির সাথে সানগ্লাস পরা কুল ইমোজি পুরো ডিজাইনকে দিয়েছে ফানি কিন্তু ডমিনেন্ট এক্সপ্রেশন। এই লেখাটি মজার ছলে এমন একজনকে বোঝায়, যে নিজের এলাকায় পরিচিত ও আত্মবিশ্বাসী। উজ্জ্বল গ্রেডিয়েন্ট কালার ডিজাইনটিকে আরও আকর্ষণীয় করে তুলেছে এবং দূর থেকেই চোখে পড়ে। যারা হাস্যরসের মাধ্যমে নিজের স্টাইল ও লোকাল ভাইব প্রকাশ করতে ভালোবাসে, তাদের জন্য এই ডিজাইনটি একদম মানানসই।', 990, 'Thu Jan 22 2026 10:18:24 GMT+0600 (Bangladesh Standard Time)', 'Thu Jan 22 2026 14:55:24 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Joke It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-40/1769077101770---.png', 't-shirt-40', 'ACTIVE');
