INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('1ffb0c85-9fe8-434a-93d9-492be805d814', 'Sorry I Can’t Hear You, I’m Gaming – Funny Gamer Quote T-Shirt', 'This design is made for gamers who live inside their headphones and ignore the world when the game starts. “Sorry I Can’t Hear You, I’m Gaming” is more than a funny line—it reflects dedication, focus, and love for gaming culture. The layered typography and headset graphics highlight immersion and attitude, making it instantly relatable to gamers. Whether you play competitively or casually, this design speaks your mindset loud and clear and turns your gaming passion into a bold visual statement.', 990, 'Mon Jan 26 2026 13:33:52 GMT+0600 (Bangladesh Standard Time)', 'Mon Jan 26 2026 15:22:24 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Game On', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/sorry-i-cant-hear-you-im-gaming-funny-gamer-quote-t-shirt/1769434429213-Gemini_Generated_Image_68ahsk68ahsk68ah-1.png', 'sorry-i-cant-hear-you-im-gaming-funny-gamer-quote-t-shirt', 'ACTIVE');
