INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('5d0787ec-3973-4ce8-9cd7-4677513776ff', 'Don’t Overthink – Clean Bold Minimalistic Typography T-Shirt', 'This design delivers a powerful yet simple reminder through bold typography and expressive visual elements. The stacked word layout emphasizes urgency, while the diagonal strike lines visually represent breaking through overthinking patterns. Carefully chosen colors balance energy and calm, symbolizing the shift from mental noise to clarity. The clean background keeps full attention on the message, making the design impactful without being overwhelming. It communicates confidence, self-awareness, and mental strength, making it perfect for individuals who value mindfulness, productivity, and a focused mindset. The overall composition feels modern, motivational, and visually striking while staying minimal and message-driven.', 990, 'Thu Jan 29 2026 12:59:01 GMT+0600 (Bangladesh Standard Time)', 'Thu Jan 29 2026 21:58:37 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/dont-overthink-clean-bold-minimalistic-typography-t-shirt/1769691538859-Dont-over-think.png', 'dont-overthink-clean-bold-minimalistic-typography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('fb6c77e6-faf2-4cc0-a231-adb303da7342', 'Born to Score Basketball Lover & Player Minimal T-Shirt', 'This “Born To Score” basketball typography design captures the spirit of confidence, competition, and pure love for the game. The bold orange text instantly stands out, while the basketball-inspired curved lines add depth, motion, and an authentic sports feel. The design reflects determination, skill, and the mindset of players who live to score and shine on the court. Clean typography combined with strong visual balance makes this artwork ideal for basketball fans, players, and sports enthusiasts who want to express their passion through powerful graphic style.', 990, 'Fri Jan 30 2026 01:47:06 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 02:45:46 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/born-to-score-basketball-lover-and-player-minimal-t-shirt/1769737625259-Born-to-score.png', 'born-to-score-basketball-lover-and-player-minimal-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('eff58f85-82cf-47d9-bc70-9d2b8f77d1e4', 'Lawyer Loading – Smart Legal Law Student T-Shirt', '“Lawyer Loading” is a smart, humorous typography design that perfectly captures the mindset of a legal professional at work. The balance scale and stacked law books visually represent justice, knowledge, and experience, while the loading text adds a playful twist that every lawyer can relate to. This design reflects patience, confidence, and sharp thinking—because when a lawyer is loading, something powerful is coming next. Ideal for advocates, attorneys, and law students who appreciate subtle legal humor, this design turns everyday professional identity into a statement worth wearing.', 990, 'Fri Jan 30 2026 04:20:55 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 20:10:18 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/lawyer-loading-smart-legal-law-student-t-shirt/1769746854332-Lawyer-loading.png', 'lawyer-loading-smart-legal-law-student-t-shirt', 'ACTIVE');
