INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('d97a1781-3c85-4721-860c-919b775b9ba6', 'Shoe – Minimal Icon Typography Funny Design T-Shirt', 'This Shoe design plays with simplicity and visual wit. The bold typography is intentionally minimal, while the shoe icon replaces part of the word to create a smart, eye-catching concept. The dark, clean layout keeps the focus on form and idea rather than clutter, making the humor feel confident and modern. It’s a design that proves you don’t need complexity to make an impact—just a clear concept and strong visuals that speak for themselves. Perfect for fans of minimalist humor and clever graphic ideas.', 990, 'Thu Feb 05 2026 01:20:13 GMT+0600 (Bangladesh Standard Time)', 'Thu Feb 05 2026 01:30:21 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/shoe-minimal-icon-typography-funny-design-t-shirt/1770254413438-04.02.2026-29.png', 'shoe-minimal-icon-typography-funny-design-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('fd694660-93e7-4025-bb9b-8db04fe6fd13', 'Done is Better Than Perfect – Action Driven Motivational T-Shirt', 'The “Done Is Better Than Perfect” t-shirt design is made for people who believe action creates success. This bold typography delivers a clear mindset message: stop waiting, stop doubting, and start doing. The strong letter structure and clean color contrast make the message instantly readable and impactful, even from a distance. This design represents productivity, confidence, and forward momentum—perfect for entrepreneurs, creators, students, and anyone chasing goals. Wearing this t-shirt is more than style; it’s a statement that you value progress, learning, and execution over fear and perfectionism.', 990, 'Fri Jan 30 2026 02:01:01 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 02:47:54 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/done-is-better-than-perfect-action-driven-motivational-t-shirt/1769738458927-Done-Is-better-than-.png', 'done-is-better-than-perfect-action-driven-motivational-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('2a5a169d-2818-4ca6-9996-03c1801d942d', 'Find Your Fire – Flame Motivational T-Shirt', 'The “Find Your Fire” design is a visual reminder to reconnect with the passion that pushes you forward. The illustrated flame symbolizes energy, courage, and inner strength, while the handwritten typography adds a raw, personal feel to the message. This design speaks to dreamers, creators, and go-getters who refuse to live without purpose. It represents the spark that starts change, growth, and action, making it more than just a phrase—it’s a mindset. Wearing this design is about showing confidence, motivation, and the courage to chase what truly matters, even when the path feels uncertain or challenging.', 990, 'Fri Jan 30 2026 02:05:23 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 02:48:24 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/find-your-fire-flame-motivational-t-shirt/1769738720941-Find-your-fire.png', 'find-your-fire-flame-motivational-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('0084e4df-937b-4d35-9d0a-f44c50ab4cd6', 'Lawyer I’m Not Arguing – I’m Explaining Why I’m Right Funny T-Shirt', 'This lawyer-themed typography design is built around confidence, logic, and sharp humor. The phrase “I’m Not Arguing, I’m Just Explaining Why I’m Right” perfectly represents how lawyers see debate—as facts, reasoning, and clarity rather than conflict. Bold lettering ensures the message dominates visually, while gold ribbon elements and justice scale symbols reinforce legal authority and professionalism. The clean black background enhances contrast, making the statement powerful and easy to read from a distance. Ideal for lawyers, advocates, and law students who enjoy expressing their courtroom mindset with humor, this design turns legal confidence into a bold, wearable statement.', 990, 'Fri Jan 30 2026 02:27:03 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 02:53:41 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Joke It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/lawyer-im-not-arguing-im-explaining-why-im-right-funny-t-shirt/1769740020936-I-am-not-arguing.png', 'lawyer-im-not-arguing-im-explaining-why-im-right-funny-t-shirt', 'ACTIVE');
