INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('2a0923a3-d978-4ac5-bcb0-ae4b81ba34a2', 'Unstoppable Shot – Explosive Football Impact Minimal Design T-Shirt', 'Unstoppable Shot captures the raw power of football in motion. The design features a football exploding through space, surrounded by cracked shockwaves and sharp speed lines that emphasize force and acceleration. Minimal yet aggressive, the artwork focuses on movement and impact rather than unnecessary details. It represents confidence, skill, and the fearless mindset of players who take decisive shots without hesitation. This design speaks to football lovers who believe in pressure, power, and making every strike count on and off the field.', 990, 'Thu Feb 05 2026 00:54:00 GMT+0600 (Bangladesh Standard Time)', 'Thu Feb 05 2026 01:30:05 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/unstoppable-shot-explosive-football-impact-minimal-design-t-shirt-2/1770252838463-04.02.2026-20.png', 'unstoppable-shot-explosive-football-impact-minimal-design-t-shirt-2', 'ACTIVE');
