INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('a70a1393-6e59-4967-9e66-02a61e91a920', 'F Caw F Funny Chicken Pun Humor T-Shirt', 'This design features a funny and clever pun “F-CAW-F” alongside a wide-eyed cartoon chicken that perfectly matches the humor. The playful typography combined with the expressive character creates a bold and entertaining visual. It’s ideal for anyone who loves animal humor, puns, and slightly edgy jokes. A great conversation starter that blends wit and creativity in a fun, memorable way.', 990, 'Sat Mar 28 2026 22:50:08 GMT+0600 (Bangladesh Standard Time)', 'Sun Mar 29 2026 12:20:53 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Joke It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/f-caw-f-funny-chicken-pun-humor-t-shirt/1774738205861-F-caw-f.png', 'f-caw-f-funny-chicken-pun-humor-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('b1cda5a6-b342-4aff-9f90-8ffc4f18cfd1', 'Bike Power Icon – Minimal Lightning Ride Design T-Shirt', 'Bike Power Icon is a modern minimal design built around movement and energy. The circular elements echo bike wheels, while the lightning-style letter detail adds a sense of speed and electric intensity. The dark, clean silhouette keeps the focus on form and symbolism rather than clutter. This design represents independence, momentum, and the passion of riders who see biking as more than transport—it’s a lifestyle. Perfect for those who love minimal visuals with strong meaning and a powerful riding attitude.', 990, 'Thu Feb 05 2026 00:58:34 GMT+0600 (Bangladesh Standard Time)', 'Thu Feb 05 2026 01:30:10 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/bike-power-icon-minimal-lightning-ride-design-t-shirt-2/1770253112477-04.02.2026-22.png', 'bike-power-icon-minimal-lightning-ride-design-t-shirt-2', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('d8d11238-27db-47b9-95f9-e658206000b8', 'Retro Film Camera Outline – Minimal Vintage Cinematography T-Shirt', 'This design captures the essence of classic filmmaking with a sleek outline illustration of a vintage film camera standing on a tripod. The minimalist line-art style keeps the focus on the iconic silhouette, symbolizing creativity, storytelling, and the golden era of cinema. The bold rectangular frame adds structure and visual impact, while the subtle retro aesthetic reflects a deep appreciation for traditional cinematography. Perfect for filmmakers, movie lovers, and anyone inspired by behind-the-scenes magic, this design represents passion for film, direction, and the art of visual storytelling.', 990, 'Mon Feb 16 2026 13:04:39 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:10:21 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Frame It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/retro-film-camera-outline-minimal-vintage-cinematography-t-shirt/1771247078001-Retro-flim-camera.png', 'retro-film-camera-outline-minimal-vintage-cinematography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('a225adde-0de4-499b-91e6-eedcaad40f99', 'Muhammad Rasul Allah Arabic Calligraphy Faith Design T-Shirt', 'এই ইসলামিক ডিজাইনটিতে “মুহাম্মদ রাসূলুল্লাহ ﷺ” বাক্যটি বৃত্তাকার আরবি ক্যালিগ্রাফির মাধ্যমে নান্দনিকভাবে উপস্থাপন করা হয়েছে। সাদা ব্যাকগ্রাউন্ডে কালো ক্যালিগ্রাফির পরিষ্কার ও ভারসাম্যপূর্ণ বিন্যাস ডিজাইনটিকে করেছে ক্লাসিক ও মর্যাদাপূর্ণ। এটি মুসলিমদের জন্য প্রিয় নবী মুহাম্মদ ﷺ এর প্রতি ভালোবাসা, সম্মান এবং ঈমানী পরিচয়ের প্রতীক। নামাজ, জুমা, ইসলামিক মাহফিল কিংবা দৈনন্দিন পরিমিত পোশাকের সাথে এটি সহজেই মানিয়ে যায়। নিজের জন্য ব্যবহার কিংবা প্রিয়জনকে উপহার দেওয়ার জন্য এটি একটি অর্থবহ, নিরাপদ ও সম্মানজনক ইসলামিক অ্যাপারেল পছন্দ।', 995, 'Fri Jan 30 2026 02:36:37 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 02:56:00 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Islamic quotes Muslim Apparel', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', 'b21c0bc4-4d74-4403-a1ad-eb1d242bf4da', true, true, NULL, 'designs/muhammad-rasul-allah-arabic-calligraphy-faith-design-t-shirt-2/1769740597629-2.png', 'muhammad-rasul-allah-arabic-calligraphy-faith-design-t-shirt-2', 'ACTIVE');
