INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('480f644d-aeda-41c9-8e22-502131e516a4', 'Do More of What Makes You Perfect Motivational Typography T-Shirt', 'The “Do More Of What Makes You Perfect” typography design delivers a powerful message of self-belief, motivation, and intentional living. Bold block letters dominate the layout, ensuring the message stands strong and readable at a glance. The warm gold and cream tones create a sense of confidence, value, and positivity, while the structured composition keeps the design clean and impactful. This artwork represents growth, focus, and choosing actions that align with personal strengths and passion. Ideal for those who believe in self-improvement, purpose-driven life choices, and expressing motivation through strong visual typography.', 990, 'Fri Jan 30 2026 01:50:33 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 02:46:27 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Rise On', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/do-more-of-what-makes-you-perfect-motivational-typography-t-shirt/1769737831588-Do-more-what.png', 'do-more-of-what-makes-you-perfect-motivational-typography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('fe2486a8-9ddc-480e-89eb-27c3eb626139', 'La Ilaha Illallah Arabic Calligraphy Islamic T-Shirt', 'এই ইসলামিক টি-শার্ট ডিজাইনটিতে পবিত্র কালিমা শাহাদাহ “লা ইলাহা ইল্লাল্লাহ মুহাম্মাদুর রাসূলুল্লাহ” এর সুন্দর ও ভারসাম্যপূর্ণ আরবি ক্যালিগ্রাফি ব্যবহার করা হয়েছে। কালো ব্যাকগ্রাউন্ডে সাদা ক্যালিগ্রাফি ডিজাইনটি একদিকে যেমন মার্জিত, অন্যদিকে তেমনি শক্তিশালী ইসলামিক বার্তা বহন করে। এটি মুসলিমদের ঈমান ও আল্লাহর একত্ববাদের ঘোষণা প্রকাশ করে। নামাজ, জুমা, ঈদ, ইসলামিক দাওয়াত, মসজিদে যাওয়া কিংবা সাধারণ দৈনন্দিন পোশাক হিসেবেও এটি মানানসই। নিজে পরার পাশাপাশি প্রিয়জনকে উপহার দেওয়ার জন্যও এটি একটি অর্থবহ ও সুন্দর নির্বাচন।', 995, 'Fri Jan 30 2026 01:56:22 GMT+0600 (Bangladesh Standard Time)', 'Fri Jan 30 2026 02:47:01 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Islamic quotes Muslim Apparel', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', 'b21c0bc4-4d74-4403-a1ad-eb1d242bf4da', true, true, NULL, 'designs/la-ilaha-illallah-arabic-calligraphy-islamic-t-shirt/1769738180345-Islamic-1.png', 'la-ilaha-illallah-arabic-calligraphy-islamic-t-shirt', 'ACTIVE');
