INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('f5d74998-8677-4672-81a1-5318563c7063', 'Running on Empty – Funny Low Energy Fuel Gauge Design T-Shirt', 'The Running on Empty funny design turns everyday exhaustion into a visual joke everyone understands. A near-empty fuel gauge, paired with a worn-out figure trapped inside, humorously represents life when energy is completely drained. The minimal line art keeps the design clean, while the bold red needle adds dramatic emphasis and comic timing. This artwork speaks to late nights, overworked routines, and those moments when coffee feels like fuel. It’s a lighthearted way to laugh at burnout, making tiredness feel relatable, expressive, and amusing rather than frustrating.', 990, 'Wed Feb 04 2026 17:41:19 GMT+0600 (Bangladesh Standard Time)', 'Wed Feb 04 2026 20:53:52 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Joke It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/running-on-empty-funny-low-energy-fuel-gauge-design-t-shirt/1770226878971-04.02.2026-09.png', 'running-on-empty-funny-low-energy-fuel-gauge-design-t-shirt', 'ACTIVE');
