INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('7205a446-7bee-483f-bdc8-13f308fe66e4', 'Running on Empty – Minimal Funny Fuel Gauge Exhaustion T-Shirt', 'This Running on Empty minimal design captures modern burnout with smart visual humor. A simple human figure leaning backward as the fuel gauge hits empty perfectly symbolizes those days when energy is gone but life keeps pulling. The stripped-down shapes and dark contrast keep the design clean, while the red needle adds emphasis and comic timing. It’s a quiet but powerful joke about fatigue, overwork, and running on fumes. Ideal for anyone who appreciates minimal art with meaning, this design turns exhaustion into something expressive, relatable, and subtly funny.', 990, 'Wed Feb 04 2026 21:26:02 GMT+0600 (Bangladesh Standard Time)', 'Wed Feb 04 2026 21:29:47 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Joke It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/running-on-empty-minimal-funny-fuel-gauge-exhaustion-t-shirt-2/1770240362353-04.02.2026-11.png', 'running-on-empty-minimal-funny-fuel-gauge-exhaustion-t-shirt-2', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('fdaff779-0de2-49ed-a4cd-64cd62f5659a', 'Scene Take Clapperboard Icon – Minimal Cinematic Filmmaker T-Shirt', 'This design captures the iconic symbol of filmmaking with a sleek clapperboard graphic set against a striking yellow circular background. The clean “Scene” and “Take” text reinforces the authentic movie-production atmosphere, representing the exact moment when creativity turns into action. The minimalist flat style combined with bold contrast makes the design visually impactful while maintaining a professional cinematic feel. Ideal for filmmakers, directors, editors, and movie enthusiasts, this artwork reflects passion for storytelling, production, and the magic that happens behind the camera when the director calls action.', 990, 'Mon Feb 16 2026 13:13:42 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:32:46 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Frame It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/scene-take-clapperboard-icon-minimal-cinematic-filmmaker-t-shirt/1771247619528-scene-take.png', 'scene-take-clapperboard-icon-minimal-cinematic-filmmaker-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('013cd803-38df-4e39-9af5-51335f04df51', 'Foot Wordplay – Minimal Typography Footprint Design T-Shirt', 'This Foot wordplay design blends minimal typography with clever visual storytelling. Instead of relying on extra elements, the footprint shape becomes part of the word itself, creating a smooth and memorable concept. The rounded forms and balanced spacing give the design a calm, modern feel while the footprint adds a light touch of humor. It’s simple, creative, and visually satisfying—perfect for people who appreciate smart design ideas that speak without being loud. A minimalist graphic that proves creativity shines best when it’s clean and intentional.', 990, 'Thu Feb 05 2026 01:27:32 GMT+0600 (Bangladesh Standard Time)', 'Thu Feb 05 2026 01:30:23 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, 'designs/foot-wordplay-minimal-typography-footprint-design-t-shirt/1770254851707-04.02.2026-31.png', NULL, 'foot-wordplay-minimal-typography-footprint-design-t-shirt', 'ACTIVE');
