INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('7aba5cb8-e364-4617-96b1-54b09f3bea1d', 'Science Doesn’t Care What You Believe – Vintage Retro Atom T-Shirt', 'This design combines a classic retro sunset color palette with a bold atomic symbol to express a timeless message: science operates on evidence, not opinion. The vintage distressed typography enhances the old-school aesthetic while reinforcing the strength of the statement. The centered atom graphic symbolizes physics, chemistry, and the fundamental laws that govern reality. Designed for science lovers, researchers, students, and rational thinkers, this artwork reflects confidence in logic, curiosity, and critical thinking. A clean yet impactful concept that visually celebrates facts, knowledge, and intellectual integrity.', 990, 'Mon Feb 16 2026 13:17:23 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:33:36 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/science-doesnt-care-what-you-believe-vintage-retro-atom-t-shirt/1771247841218-science-dosent-care.png', 'science-doesnt-care-what-you-believe-vintage-retro-atom-t-shirt', 'ACTIVE');
