INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('5fea9aba-d686-4d8a-b5f6-2d944dca75e5', 'Minimal Music Icons Set – Guitar, Mic & Drum Badge Design T-Shirt', 'This design showcases a minimalist set of four circular music icons, each representing a core element of musical expression. Guitar headstocks, a microphone, and a drum form are drawn in a simple yet confident line style, creating a cohesive badge-style layout. The circular frames add structure and harmony, while the icons themselves communicate passion for music without words. The overall composition feels modern, clean, and symbolic—perfect for those who see music not just as sound, but as identity. It’s a visually strong concept that celebrates different roles and instruments within the world of music in a single, unified design.', 990, 'Thu Feb 05 2026 02:33:20 GMT+0600 (Bangladesh Standard Time)', 'Thu Feb 05 2026 15:53:37 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/minimal-music-icons-set-guitar-mic-and-drum-badge-design-t-shirt-2/1770258798382-04.02.2026-42.png', 'minimal-music-icons-set-guitar-mic-and-drum-badge-design-t-shirt-2', 'ACTIVE');
