INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('8ca6adbc-0477-4b97-9c3c-0e4727902ef7', 'Science It’s Like Magic But Real – Vintage Retro Atom Badge T-Shirt', 'This vintage-inspired circular badge design celebrates the beauty of science with the bold statement, “It’s Like Magic But Real.” The retro sunset color palette enhances the nostalgic aesthetic, while the centered atom symbol represents physics, chemistry, and the fundamental forces shaping our universe. The distressed texture adds character and depth, giving the design a classic worn-in feel. Ideal for science lovers, students, teachers, researchers, and STEM enthusiasts, this artwork expresses curiosity, logic, and appreciation for real-world phenomena that feel magical—but are grounded in evidence and truth.', 990, 'Mon Feb 16 2026 15:39:32 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 16:52:58 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/science-its-like-magic-but-real-vintage-retro-atom-badge-t-shirt/1771256369904-Science-its-like-magic.png', 'science-its-like-magic-but-real-vintage-retro-atom-badge-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('4c2a5849-0e7e-46e8-a8ba-a0b48eb4deb1', 'Think Like a Proton – Always Positive Science T-Shirt', 'This science-inspired typography design combines humor and motivation in one smart visual statement. Featuring the witty quote “Think Like a Proton – Always Positive,” the layout uses bold, high-impact text to emphasize the uplifting message. The central atom graphic, with colorful orbiting electrons, enhances the physics theme while keeping the design modern and eye-catching. Perfect for science lovers, physics enthusiasts, teachers, and students, this design blends STEM pride with everyday positivity in a clean, memorable way.', 990, 'Mon Feb 16 2026 17:28:35 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:44:48 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/think-like-a-proton-always-positive-science-t-shirt/1771262913350-think-like-a-proton.png', 'think-like-a-proton-always-positive-science-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('00314e3f-441c-40a5-a976-1dba5c4dcf6c', 'Trust Me I’m an Engineer – Funny Engineer Quote T-Shirt', '“Trust Me I’m An Engineer” is a bold and humorous typography design that perfectly blends confidence with technical pride. The clean uppercase lettering delivers a strong visual impact, while the illustrated yellow hard hat and safety goggles icon instantly communicate engineering profession and expertise. The minimalist yet powerful composition makes the message clear, witty, and relatable. Ideal for engineers who appreciate smart humor and want to showcase their professional identity with a confident, playful statement.', 990, 'Mon Feb 16 2026 17:45:03 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:47:34 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Engineer Hub', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/trust-me-im-an-engineer-funny-engineer-quote-t-shirt/1771263903149-Trust-me.png', 'trust-me-im-an-engineer-funny-engineer-quote-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('6c32ad87-da3e-49f8-beee-c5c7938b962b', 'Smile and Be Happy Inspirational Typography Design – Minimal T-Shirt', 'This “Smile and Be Happy” design delivers a timeless message through clean, powerful typography. The bold uppercase words “SMILE” and “HAPPY” frame the softer handwritten “and be,” creating a beautiful contrast that symbolizes strength and gentleness together. A small heart icon above adds a subtle touch of love and positivity. The minimalist black background keeps the focus entirely on the message, making it visually striking and easy to read. Perfect for spreading good vibes, daily motivation, and positive energy wherever you go.', 990, 'Mon Feb 16 2026 16:55:41 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:17:46 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/smile-and-be-happy-inspirational-typography-design-minimal-t-shirt/1771260939111-Smile-and-be-happy.png', 'smile-and-be-happy-inspirational-typography-design-minimal-t-shirt', 'ACTIVE');
