INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('128bc0d4-f6fd-4041-8ad5-7aee1c2146de', 'Smile You’re on Camera – Photography T-Shirt', 'This “Smile You’re On Camera” design blends humor with clean minimalist style. The bold uppercase “SMILE” and “CAMERA” frame a simple outlined camera graphic, creating a balanced and eye-catching layout. The casual handwritten “you’re on” in the middle adds personality and playful energy to the message. The white typography against a black background ensures strong visibility and a striking look from a distance. Ideal for photographers, vloggers, security humor fans, or anyone who enjoys witty, lighthearted statement designs.', 990, 'Mon Feb 16 2026 16:58:37 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:18:39 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Frame It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/smile-youre-on-camera-photography-t-shirt/1771261114804-Smilee-.png', 'smile-youre-on-camera-photography-t-shirt', 'ACTIVE');
