INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('b1fad5ce-edac-4953-9508-72c96f66328f', 'Be the Change – Colorful Motivational Typography Design T-Shirt', 'The “Be The Change” design delivers a timeless motivational message through modern, colorful typography. The clean layout combined with vibrant gradient letters turns a simple quote into a powerful visual statement about mindset and action. This design represents leadership, self-belief, and the idea that real change begins from within. Perfect for those who value positivity, personal growth, and making a difference, it serves as a daily reminder to live intentionally and inspire others through action.', 990, 'Fri Feb 06 2026 06:26:37 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 16:37:38 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/be-the-change-colorful-motivational-typography-design-t-shirt/1770359196134-be-the-change.png', 'be-the-change-colorful-motivational-typography-design-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('0f4fa1cf-c6ab-49d4-be0f-ed5aeddeefbf', 'Book Heartbeat Line – Reading is Life Minimal Line Art T-Shirt', 'The Book Heartbeat Line design captures the idea that reading is more than a habit—it’s a vital part of life. An open book placed at the center of an ECG heartbeat line visually connects knowledge with emotion, intellect with passion. The simple yet powerful line-art style keeps the message clear and impactful, making the design feel calm, thoughtful, and deeply relatable. It represents love for books, learning, and intellectual growth, turning reading into a symbol of life itself for anyone who feels their heart beat faster when they open a book.', 990, 'Fri Feb 06 2026 06:50:55 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 17:30:32 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/book-heartbeat-line-reading-is-life-minimal-line-art-t-shirt/1770360653057-Book.png', 'book-heartbeat-line-reading-is-life-minimal-line-art-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('12194a20-097b-4724-9972-80683c7cb592', 'Biology Circle Icons – Cute Science Elements Illustrated T-Shirt', 'This Biology Circle Icons design brings the entire world of life science together in one harmonious visual. A wide range of illustrated elements—DNA strands, cells, microscope, plants, animals, organs, and microorganisms—are arranged in a circular form, symbolizing the interconnected nature of biology. The playful yet informative illustration style balances education with creativity, making the design visually engaging and meaningful. It reflects curiosity, learning, and passion for science, turning complex biological concepts into an inviting and aesthetically pleasing design that truly celebrates biology.', 990, 'Fri Feb 06 2026 06:48:08 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 17:31:00 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/biology-circle-icons-cute-science-elements-illustrated-t-shirt/1770360486822-Biology.png', 'biology-circle-icons-cute-science-elements-illustrated-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('775897bf-2928-4c0c-852a-cdbd4ed8d9e6', 'Best Friends – Cute Kawaii Cats Friendship Illustration T-Shirt', 'The “Best Friends” design captures the pure happiness of friendship through charming kawaii cat illustrations. Each cat has a unique expression, symbolizing different personalities united by love and companionship. Soft pastel tones and heart details add a warm, feel-good vibe that makes the design emotionally appealing at first glance. This artwork is perfect for those who celebrate friendship, cute art, and positive emotions, turning a simple message into a heart-touching visual story that people instantly fall in love with.', 990, 'Fri Feb 06 2026 06:32:14 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 17:33:05 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Kitty', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/best-friends-cute-kawaii-cats-friendship-illustration-t-shirt/1770359531802-Best-friend.png', 'best-friends-cute-kawaii-cats-friendship-illustration-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('483c609a-9a5d-4ea4-8fbd-bf4dd56b6c0f', 'Biology Emblem – Science Lab Icons Circular Biology Design T-Shirt', 'The Biology Emblem design visually celebrates the world of life science through a smart and symbolic composition. A DNA strand, microscope, leaf, and lab elements are arranged inside a circular badge, representing research, discovery, and the connection between nature and science. The monochrome green tone enhances the academic and scientific feel, making the design bold yet clean. This artwork speaks to curiosity, knowledge, and scientific passion, turning biology into a strong visual identity that feels modern, meaningful, and intellectually inspiring.', 990, 'Fri Feb 06 2026 06:38:27 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 19:17:24 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/biology-emblem-science-lab-icons-circular-biology-design-t-shirt/1770359906324-Biologgy.png', 'biology-emblem-science-lab-icons-circular-biology-design-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('6ddddb03-2c0d-4277-a792-d029f19a6d71', 'Stay Positive Work Hard Make It Happen – Bold Motivational T-Shirt', 'This “Stay Positive Work Hard Make It Happen” design delivers a strong motivational message through bold, structured typography and striking color contrast. The layered arrangement highlights key words like “WORK HARD” and “HAPPEN,” reinforcing determination and drive. The mix of script and block fonts creates visual balance, while the red and teal tones on a dark background give it a confident, high-impact presence. Perfect for entrepreneurs, students, athletes, and anyone focused on growth, hustle, and achieving goals with relentless positivity.', 990, 'Mon Feb 16 2026 17:03:20 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:19:21 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Rise On', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/stay-positive-work-hard-make-it-happen-bold-motivational-t-shirt/1771261399015-stay-positive-work-hard.png', 'stay-positive-work-hard-make-it-happen-bold-motivational-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('3bb5dea0-1494-40c5-9fac-5c128b412a84', 'Camera Typography Concept Design – Photography Words T-Shirt', 'This Camera Typography Concept Design is a celebration of photography culture, combining iconic camera imagery with essential photography terms to create a visually rich and meaningful artwork. Every word is thoughtfully placed to shape the camera body and lens, symbolising how technique and creativity come together behind every great photo. The bold monochrome style ensures high contrast and instant recognition, making the design impactful and professional. Perfect for photographers, photo editors, and visual storytellers who connect deeply with the technical language of photography, this design represents passion, skill, and dedication to the art of capturing moments.', 990, 'Fri Feb 06 2026 07:30:34 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 16:45:43 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/camera-typography-concept-design-photography-words-t-shirt/1770363031619-Camera.png', 'camera-typography-concept-design-photography-words-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('de05c5d1-f4b3-45f1-a84b-7f6e5538ffae', 'Camera is My Only Drug – Bold Photography Lover Statement T-Shirt', 'The “Camera Is My Only Drug” design is a fearless declaration for those who live through lenses and frames. Built with bold, high-impact typography, this artwork represents addiction to creativity, light, and storytelling through photography. The minimal yet commanding design ensures the message stands out instantly, making it perfect for photographers who see the camera as more than a tool—it’s a way of life. This design reflects passion, focus, and the irresistible pull of capturing moments, emotions, and realities through visuals. It’s not just a quote; it’s an identity for true camera lovers.', 990, 'Fri Feb 06 2026 07:26:10 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 16:58:45 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/camera-is-my-only-drug-bold-photography-lover-statement-t-shirt/1770362769296-camera-is-my-only-drug.png', 'camera-is-my-only-drug-bold-photography-lover-statement-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('eb87a8a5-ac65-4b34-81b1-27089cfd2bcd', 'Retro Cassette Tape Splash – Vintage Music Vibes T-Shirt', 'The Retro Cassette Tape Splash design is a bold celebration of classic music culture and analog nostalgia. Featuring a detailed cassette tape set against an explosive splash of warm colors, this artwork captures the raw energy of vintage sound and creative expression. The design instantly evokes memories of mixtapes, rewind buttons, and timeless playlists. Its dynamic composition and retro color palette make it visually striking while delivering a strong emotional connection for music lovers. This design isn’t just about music—it represents individuality, passion, and the everlasting charm of old-school vibes in a modern artistic form.', 990, 'Fri Feb 06 2026 07:14:55 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 16:59:07 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/retro-cassette-tape-splash-vintage-music-vibes-t-shirt/1770362092052-Caeset.png', 'retro-cassette-tape-splash-vintage-music-vibes-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('7974a3a0-b224-4da7-b5c9-aba20a4c0077', 'Brain ON / OFF – Minimal Mind Control Switch Concept Design T-Shirt', 'The Brain ON / OFF design is a smart and witty visual expression of modern thinking. Featuring a minimalist switch-style illustration, it perfectly represents focus, awareness, and control over one’s mindset. The clean layout and strong contrast make the message instantly readable and visually striking. This design speaks to thinkers, creators, students, and anyone who values mental clarity and intentional living. It’s not just a graphic—it’s a statement about knowing when to activate your mind and when to switch off the noise, making it both meaningful and visually impactful.', 990, 'Fri Feb 06 2026 07:06:17 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 17:06:32 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/brain-on-off-minimal-mind-control-switch-concept-design-t-shirt/1770361575241-Brain-on.png', 'brain-on-off-minimal-mind-control-switch-concept-design-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('4d63f675-1c24-4996-bfce-54f58567fc6e', 'Born to Drum – Vintage Drummer Passion Typography Design T-Shirt', 'The Born to Drum design is a celebration of rhythm, passion, and identity. Featuring bold vintage typography paired with a detailed drum kit illustration, this artwork speaks directly to those who live and breathe beats. The retro-inspired color tone adds a timeless feel, while the strong central composition makes the message impossible to ignore. It represents dedication to music, late-night practice sessions, and the unstoppable energy of a drummer’s soul. This design isn’t just about playing drums—it’s about being born with rhythm in your blood and proudly showing that passion to the world.', 990, 'Fri Feb 06 2026 06:59:52 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 17:30:01 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/born-to-drum-vintage-drummer-passion-typography-design-t-shirt/1770361190769-Born-to-drum.png', 'born-to-drum-vintage-drummer-passion-typography-design-t-shirt', 'ACTIVE');
