INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('f2b325f4-77c3-4ebe-9f49-842b79790b4f', 'Birthday Boy Construction Theme Design T-Shirt', 'Creative birthday design with construction vehicles and bold industrial graphics. Ideal for young truck lovers and construction fans celebrating their special day. The strong visual style gives a fun and playful look perfect for birthday parties and casual wear.
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('bc9ce380-db52-4d6a-9f52-e3f56bfb8430', 'Science Teacher Periodic Table Typography – Te Ac H Er T-Shirt', 'This smart and visually striking design celebrates science educators with a clever periodic table twist. The word “Teacher” is formed using authentic element blocks—Tellurium (Te), Actinium (Ac), Hydrogen (H), and Erbium (Er)—adding a layer of intellectual creativity that chemistry lovers instantly appreciate. Above, bold “SCIENCE” typography is supported by clean lab-inspired graphics including atoms, molecular bonds, flasks, stacked books, and a microscope, symbolizing curiosity, experimentation, and knowledge. Perfect for chemistry teachers, STEM instructors, professors, and science mentors who proudly represent logic, discovery, and education every day.', 990, 'Mon Feb 16 2026 15:49:39 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 16:53:02 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/science-teacher-periodic-table-typography-te-ac-h-er-t-shirt/1771256977643-science-teacher.png', 'science-teacher-periodic-table-typography-te-ac-h-er-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('8a1cb239-223e-4134-bc15-cf4951fb1103', 'CEO Mindset Typography – Leader Founder Business Vision T-Shirt', 'The CEO Mindset Typography design is a bold visual statement for leaders, founders, and entrepreneurs. The word “CEO” is constructed entirely from impactful terms such as leader, founder, strategist, planner, creator, and business owner, reflecting the mental framework behind success and authority. The clean monochrome style enhances clarity and power, making the message instantly recognizable and professional. This design represents ambition, control, vision, and leadership—perfect for those who think big, lead teams, and build businesses with confidence and purpose.', 990, 'Fri Feb 06 2026 08:31:00 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 18:29:37 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'CEO', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/ceo-mindset-typography-leader-founder-business-vision-t-shirt/1770366658127-CEO.png', 'ceo-mindset-typography-leader-founder-business-vision-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('cdac0851-14f0-414c-8d70-e1e6d6258891', 'Chocolate Chemistry Design – Science Meets Sweet Obsession T-Shirt', 'The Chocolate Chemistry Design is a clever fusion of science and sweetness, made for those who love chocolate and appreciate the science behind it. Featuring a molecular structure linked to chocolate’s mood-boosting compounds alongside a rich chocolate bar graphic, this design tells a story where chemistry explains happiness. The minimal black background enhances the contrast, making the visuals stand out while keeping the concept smart and witty. Perfect for science lovers, chemistry students, or anyone who proudly believes chocolate is basically science-approved happiness.', 990, 'Fri Feb 06 2026 08:49:49 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 18:30:39 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/chocolate-chemistry-design-science-meets-sweet-obsession-t-shirt/1770367787288-Choclste.png', 'chocolate-chemistry-design-science-meets-sweet-obsession-t-shirt', 'ACTIVE');
