INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('77e64838-69c4-4b7e-8e8e-7b94364f06ec', 'Porsche 911 Turbo Retro Red Sports Car T-Shirt', 'This design showcases the legendary Porsche 911 Turbo in a striking retro composition. The bold typography at the bottom reinforces the model’s identity, while the detailed red-and-white sports car illustration captures timeless performance and German engineering excellence. The strong red background block enhances contrast and gives the artwork a classic poster-style aesthetic. Perfect for automotive enthusiasts, collectors, and fans of iconic turbocharged sports cars who appreciate speed, legacy, and design precision.', 990, 'Mon Feb 16 2026 12:10:48 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:05:48 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Gearsift', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/porsche-911-turbo-retro-red-sports-car-t-shirt/1771243848229-porsche-911-turbo.png', 'porsche-911-turbo-retro-red-sports-car-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('e3b2306b-b871-4d89-bf40-4f258418c0c6', 'Minimal Science Typography Design – Clean Academic T-Shirt', 'This minimalist science design delivers maximum impact through simplicity. Featuring bold, oversized “SCIENCE” typography with a subtle vintage distressed texture, the artwork makes a confident academic statement without clutter or distractions. The clean contrast enhances readability while maintaining a modern aesthetic that appeals to teachers, students, researchers, and STEM professionals alike. Whether you love physics, chemistry, biology, or general scientific exploration, this design represents curiosity, logic, and evidence-based thinking in its purest visual form. A timeless graphic for anyone proud to stand with science.', 990, 'Mon Feb 16 2026 16:11:19 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 16:54:37 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/minimal-science-typography-design-clean-academic-t-shirt/1771258278090-Science_.png', 'minimal-science-typography-design-clean-academic-t-shirt', 'ACTIVE');
