INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('42c06ed6-8100-4f2a-b383-4d3d11728fa8', 'Rubik’s Cube Math Concept Design – Logic, Formula & Problem T-Shirt', 'The Rubik’s Cube Math Concept design is a powerful visual celebration of logic and analytical thinking. A vibrant cube sits at the center, surrounded by chalk-style equations, geometry diagrams, and mathematical symbols that evoke classrooms, curiosity, and mental challenges. The rotating arrow adds motion and depth, symbolizing problem-solving, learning, and intellectual growth. This artwork perfectly captures the mindset of thinkers who enjoy puzzles, mathematics, and brain-training challenges. Bold contrast and clever composition make the design visually striking and intellectually inspiring.', 990, 'Fri Feb 06 2026 14:59:25 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 18:55:58 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/rubiks-cube-math-concept-design-logic-formula-and-problem-t-shirt/1770389963288-Cube.png', 'rubiks-cube-math-concept-design-logic-formula-and-problem-t-shirt', 'ACTIVE');
