INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('7e75e6ba-d3ed-4fc7-99ae-26ab812638ba', 'Colorful Science Icons Typography Design – STEM Cartoon T-Shirt', 'This colorful science design brings the world of STEM to life through vibrant typography and detailed cartoon-style icons. The bold “SCIENCE” lettering stands at the center, surrounded by carefully illustrated elements such as atoms, DNA strands, microscopes, molecules, planets, laboratory glassware, and symbols of innovation. The balanced layout and bright color palette create an engaging, energetic academic theme that celebrates physics, chemistry, biology, and scientific exploration. Perfect for teachers, students, researchers, and science enthusiasts who love curiosity, experimentation, and knowledge-driven creativity expressed through a fun and visually dynamic graphic.', 990, 'Mon Feb 16 2026 16:25:51 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 16:54:44 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/colorful-science-icons-typography-design-stem-cartoon-t-shirt/1771259150365-Science.png', 'colorful-science-icons-typography-design-stem-cartoon-t-shirt', 'ACTIVE');
