INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('2e65e8a7-9414-4a83-aafd-ff2f845811ad', 'Floating Astronaut Illustration – Minimal Space Exploration T-Shirt', 'This floating astronaut design represents freedom, curiosity, and the quiet beauty of space exploration. The simple yet expressive illustration shows an astronaut drifting effortlessly while holding onto a rope, symbolizing the balance between exploration and connection. The dark background enhances the feeling of depth and isolation, making the astronaut stand out as a symbol of bravery and imagination. This design speaks to dreamers, space lovers, and those who enjoy minimal yet meaningful visuals that reflect adventure, discovery, and the desire to go beyond limits.', 990, 'Fri Feb 06 2026 06:03:05 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 16:34:45 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/floating-astronaut-illustration-minimal-space-exploration-t-shirt/1770357782338-Astronote.png', 'floating-astronaut-illustration-minimal-space-exploration-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('7134767d-7fbe-4820-92c4-921ebeffdb61', 'Always Believe in Yourself – Bold Motivational Typography T-Shirt', 'The “Always Believe in Yourself” design transforms a timeless motivational message into a strong visual statement. The bold typography commands attention, while the subtle broken line through the word “BELIEVE” represents overcoming fear, doubt, and hesitation. The clean frame adds structure and authority, making the message feel confident and intentional rather than decorative. This design speaks directly to mindset and self-belief, encouraging persistence and inner strength. It’s made for people who value motivation, personal growth, and the courage to trust themselves every single day.', 990, 'Fri Feb 06 2026 05:56:06 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 16:38:13 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/always-believe-in-yourself-bold-motivational-typography-t-shirt/1770357363476-Always-belive-in-yourself.png', 'always-believe-in-yourself-bold-motivational-typography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('4915255a-9871-43d0-83d5-ba70b7db242c', 'Dream Plan Start – Motivational Action Quote Design T-Shirt', 'The Dream Plan Start design is a strong visual reminder that success begins with action. Using a bold, distressed layout, the artwork clearly separates each stage of progress—dreaming, planning, and starting—so the message feels structured and impactful. The combination of heavy typography and handwritten script adds contrast and emotion, while the arrows visually push the viewer toward movement and decision. This design speaks directly to entrepreneurs, creators, and goal-setters who believe ideas only matter when acted upon. Motivational, confident, and visually striking, it encourages turning thoughts into real progress.', 990, 'Fri Feb 06 2026 16:20:24 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 19:10:14 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/dream-plan-start-motivational-action-quote-design-t-shirt/1770394821392-Dream-plan-start.png', 'dream-plan-start-motivational-action-quote-design-t-shirt', 'ACTIVE');
