INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('b9ea2da4-7997-4c9d-9ab7-c949d1e2e354', 'Vintage Camera Illustration Design – Retro Photography T-Shirt', 'This Vintage Camera Illustration Design captures the essence of classic photography through a beautifully balanced retro camera artwork. The warm color palette and carefully drawn details bring out the nostalgic feel of analog cameras, symbolising a deep love for traditional photography and visual storytelling. Every element—from the prominent lens to the mechanical buttons—reflects precision, creativity, and passion for capturing moments the old-fashioned way. Ideal for photographers, camera lovers, and retro design enthusiasts, this design stands as a tribute to the timeless beauty of photography beyond trends and technology.', 990, 'Fri Feb 06 2026 07:36:27 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 16:43:50 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/vintage-camera-illustration-design-retro-photography-t-shirt/1770363384759-Cameraaa.png', 'vintage-camera-illustration-design-retro-photography-t-shirt', 'ACTIVE');
