INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('a5f32638-1df3-4a02-acb5-6e52df624a92', 'Collect Moments Not Things – Artistic Camera Quote Design T-Shirt', 'The Collect Moments Not Things design is a visual reminder to value experiences, memories, and stories rather than material objects. Centered around a creatively illustrated camera decorated with colorful geometric accents, the design symbolizes capturing life’s most meaningful moments. The handwritten-style quote reinforces a mindful, minimalist philosophy that resonates with photographers, travelers, and anyone who believes memories are life’s true treasures. The dark background enhances contrast, making the artwork and message stand out clearly while keeping the overall look artistic, modern, and emotionally engaging.', 990, 'Fri Feb 06 2026 08:54:44 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 18:44:08 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/collect-moments-not-things-artistic-camera-quote-design-t-shirt/1770368082574-Collect-moment-.png', 'collect-moments-not-things-artistic-camera-quote-design-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('d4bc72ea-be5a-4177-92c0-d8f40a95236e', 'Cricket Typography Emblem Design – Minimal Sports Power T-Shirt', 'The Cricket Typography Emblem design is a striking visual tribute to the spirit of cricket. Each letter is thoughtfully crafted with iconic cricket elements—bat, helmet, stumps, and ball—merged seamlessly into the typography. The dark, textured finish gives the design a bold and professional presence, symbolizing focus, strategy, and dedication to the game. This artwork speaks directly to true cricket lovers who see the sport not just as a game, but as an identity, emotion, and lifelong passion. Clean composition and strong symbolism make this design powerful and timeless.', 990, 'Fri Feb 06 2026 14:51:41 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 18:55:40 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/cricket-typography-emblem-design-minimal-sports-power-t-shirt-2/1770389499738-Cricket-w.png', 'cricket-typography-emblem-design-minimal-sports-power-t-shirt-2', 'ACTIVE');
