INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('8db7e91e-2ba8-4fe8-bb2d-666bb74136e4', 'E = Mc² Coffee Humor Design – Energy Equals Milk × Coffee T-Shirt', 'The E = mc² Coffee Humor design is a smart and funny take on one of the most iconic formulas in science. By redefining energy as milk multiplied by coffee, the design turns academic symbolism into an everyday truth for caffeine lovers. The simple, chalkboard-inspired typography gives it a classroom-meets-coffeehouse vibe, making the message feel witty and intellectual at the same time. This artwork is perfect for people who love science jokes, study humor, and clever wordplay, delivering a lighthearted reminder that real-world energy often comes from a good cup of coffee.', 990, 'Fri Feb 06 2026 16:27:27 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 19:10:41 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/e-mc-coffee-humor-design-energy-equals-milk-coffee-t-shirt/1770395245629-E-mc2.png', 'e-mc-coffee-humor-design-energy-equals-milk-coffee-t-shirt', 'ACTIVE');
