INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('e19c2bb8-b806-424e-9df3-d51409f3806d', 'Physics Icons Design – E = Mc² Science Symbols Typography T-Shirt', 'The Physics Icons Design – E = mc² artwork transforms core science elements into a charming and educational visual composition. Featuring instantly recognizable symbols such as the atom, formula, textbook, geometry tools, and apple, the design celebrates the spirit of learning and discovery. The smooth typography and balanced layout create a light, modern academic aesthetic that feels both smart and playful. Perfect for students, teachers, science lovers, and anyone who appreciates intellectual creativity, this design highlights physics as not just a subject—but a mindset built on curiosity and exploration.', 990, 'Fri Feb 06 2026 16:49:49 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 19:11:46 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/physics-icons-design-e-mc-science-symbols-typography-t-shirt/1770396589130-Emc-2-phusics.png', 'physics-icons-design-e-mc-science-symbols-typography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('ef501078-2dc6-4a24-8ba7-12f461adedc8', 'Eat Sleep Code Repeat – Programmer Lifestyle Typography Desi T-Shirt', 'The Eat Sleep Code Repeat design captures the core mindset of developers and programmers through bold, no-nonsense typography. Each word is stacked with purpose, visually reflecting repetition, discipline, and focus. The contrasting colors create clear separation between actions, while the highlighted “CODE” section reinforces coding as the heart of the routine. This design speaks directly to developers, software engineers, and tech enthusiasts who live by logic, loops, and late-night problem-solving. Clean, modern, and instantly recognizable, it turns a simple phrase into a strong identity statement for anyone who codes.', 990, 'Fri Feb 06 2026 19:00:35 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 19:13:13 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/eat-sleep-code-repeat-programmer-lifestyle-typography-desi-t-shirt/1770404433201-eat-sleep-code-.png', 'eat-sleep-code-repeat-programmer-lifestyle-typography-desi-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('6ec09f9f-39a3-4034-b104-2b0ed6fa7618', 'Don’t Waste Your Time – Motivational Clock Quote Design T-Shirt', 'The Don’t Waste Your Time design is a powerful visual reminder of life’s most valuable resource. Featuring a cheerful yet meaningful clock illustration combined with bold, rounded lettering, the artwork communicates urgency without negativity. The balanced composition keeps the message clear and memorable, while the playful style makes it approachable and inspiring rather than harsh. This design speaks to productivity lovers, dream chasers, and anyone who believes time should be used wisely. Simple, motivational, and visually clean, it encourages focus, action, and mindful living every single day.', 990, 'Fri Feb 06 2026 16:14:15 GMT+0600 (Bangladesh Standard Time)', 'Fri Feb 06 2026 19:15:21 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/dont-waste-your-time-motivational-clock-quote-design-t-shirt/1770394453681-Dont-waste-your-time.png', 'dont-waste-your-time-motivational-clock-quote-design-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('74be2f67-57ca-434f-a04d-084890a3169c', 'Modern Quote T Shirt T-Shirt', 'This “Physics” design celebrates the beauty of science through colorful typography and playful hand-drawn illustrations. Featuring classic physics symbols like E=mc², F=ma, atoms, rockets, magnets, graphs, and lab equipment, the artwork captures the curiosity and excitement of discovery. The chalkboard-inspired sketch style adds an authentic classroom feel, while the vibrant lettering brings modern energy. Perfect for students, teachers, scientists, and STEM enthusiasts, this design expresses passion for learning, exploration, and the fascinating laws that shape our universe.', 990, 'Mon Feb 16 2026 11:12:32 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:00:08 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/modern-quote-t-shirt-t-shirt/1771240351380-Physich-color.png', 'modern-quote-t-shirt-t-shirt', 'ACTIVE');
