INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('29a60869-66d4-4479-9b6c-62cd607ea399', 'Graphic Designer Warning Label Style Design – Funny Creative T-Shirt', 'This Graphic Designer design is styled like a bold product warning label, packed with humor and creative attitude. Featuring icons for multitasking, problem solving, coffee dependency, and travel, it perfectly captures the real-life designer experience. With sarcastic badges, caution signs, barcode detail, and “100% Organic” stamp, the layout delivers a sharp, witty statement. Ideal for graphic designers, freelancers, creative professionals, and design students who embrace the hustle with humor.', 990, 'Sun Feb 15 2026 16:30:22 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:26:22 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Joke It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/graphic-designer-warning-label-style-design-funny-creative-t-shirt/1771173021154-Graphic-designer.png', 'graphic-designer-warning-label-style-design-funny-creative-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('187e18f2-a392-44a1-a1eb-a1ea474ea002', 'Physics is the Purest Form of Magic – Atomic Science T-Shirt', 'This “Physics Is the Purest Form of Magic” design captures the awe and beauty of scientific discovery. Featuring striking golden typography and a glowing atomic symbol surrounded by dynamic energy waves, the artwork symbolizes the invisible forces that shape our universe. The clean, high-contrast layout emphasizes both intelligence and curiosity, blending logic with imagination. Ideal for physics students, teachers, researchers, and science enthusiasts, this design celebrates the idea that real magic isn’t illusion—it’s science understood at its deepest level.', 990, 'Mon Feb 16 2026 11:16:16 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:00:32 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/physics-is-the-purest-form-of-magic-atomic-science-t-shirt/1771240574575-Physich-is-the-purest-form-.png', 'physics-is-the-purest-form-of-magic-atomic-science-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('01026fdc-5132-4507-9881-f6fe3bebec53', 'Allah Name Arabic Calligraphy Minimal Faith Design T-Shirt', 'এই ইসলামিক ডিজাইনটিতে আল্লাহ তাআলার পবিত্র নামকে মিনিমাল ও বিমূর্ত আরবি ক্যালিগ্রাফির মাধ্যমে উপস্থাপন করা হয়েছে। সাদা ব্যাকগ্রাউন্ডে কালো রঙের পরিষ্কার রেখাগুলো ডিজাইনটিকে করেছে সহজ, মার্জিত ও গভীর অর্থবহ। কোনো অতিরিক্ত অলংকার বা বিভ্রান্তিকর উপাদান ছাড়াই এটি তাওহীদ ও ঈমানের মূল বার্তাকে সম্মানজনকভাবে তুলে ধরে। নামাজ, জুমা, ইসলামিক পরিবেশ কিংবা দৈনন্দিন সংযত পোশাক হিসেবে এই ডিজাইনটি মানানসই। নিজে ব্যবহার করা অথবা প্রিয়জনকে উপহার দেওয়ার জন্য এটি একটি নিরাপদ, অর্থবহ ও সময়োপযোগী ইসলামিক অ্যাপারেল পছন্দ।', 995, 'Sat Feb 07 2026 03:47:22 GMT+0600 (Bangladesh Standard Time)', 'Sat Feb 07 2026 03:54:04 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Islamic quotes Muslim Apparel', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', 'b21c0bc4-4d74-4403-a1ad-eb1d242bf4da', true, true, NULL, 'designs/allah-name-arabic-calligraphy-minimal-faith-design-t-shirt/1770436042242-Allah-Name-Arabic-Calligraphy-Minimal-Faith-Design-1.png', 'allah-name-arabic-calligraphy-minimal-faith-design-t-shirt', 'ACTIVE');
