INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('9e2316b5-931b-4d63-a82d-5f450a6fe33e', 'Engineer Typography Design – Bold Professional Statement T-Shirt', 'The Engineer Typography Design is a bold and confident statement piece created for those who build, design, and innovate. Featuring strong uppercase “ENGINEER” lettering with a clean, structured aesthetic, this graphic captures the precision and discipline associated with the engineering profession. The minimalist yet impactful layout emphasizes professionalism and technical pride. Perfect for engineers, students, or anyone passionate about innovation and problem-solving, this design visually communicates expertise, intelligence, and dedication in a sleek and modern way.', 990, 'Sun Feb 15 2026 14:14:31 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:10:23 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Engineer Hub', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/engineer-typography-design-bold-professional-statement-t-shirt/1771164869921-Engineer-1.png', 'engineer-typography-design-bold-professional-statement-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('1647ffc4-f5b0-4676-9d11-fe0edad27e16', 'Enjoy the Summer – Surf Paradise Retro Beach Graphic T-Shirt', 'The Enjoy The Summer – Surf Paradise Graphic Design captures the essence of tropical freedom and ocean adventure. A dynamic surfer silhouette rides rolling waves against colorful sunset-inspired panels, surrounded by palm trees and tropical leaves. The bold headline “ENJOY THE SUMMER” combined with the phrase “Summer Surf in Blue Paradise” enhances the laid-back, retro beach aesthetic. This design embodies sunshine, sea breeze, and endless vacation vibes—perfect for those who live for summer and the thrill of the surf.', 990, 'Sun Feb 15 2026 14:30:21 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:14:14 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Weekend ', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/enjoy-the-summer-surf-paradise-retro-beach-graphic-t-shirt/1771165819247-Enjoy-the-summer.png', 'enjoy-the-summer-surf-paradise-retro-beach-graphic-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('d8b9d971-78a6-4799-906b-b544131daf2d', 'Colorful Engineer Graphic Design – Innovation & Technology T-Shirt', 'The Colorful Engineer Graphic Design combines bold typography with detailed technical illustrations to celebrate the world of engineering. The vibrant “ENGINEER” text stands out against a background filled with gears, rockets, formulas, circuit diagrams, tools, and innovation symbols. This visually dynamic composition represents creativity, precision, and technological advancement. Designed for engineers, students, and tech enthusiasts, this artwork expresses professional pride and a passion for building the future through science and innovation.', 990, 'Sun Feb 15 2026 14:20:57 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:14:17 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Engineer Hub', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/colorful-engineer-graphic-design-innovation-and-technology-t-shirt/1771165256511-Engineer.png', 'colorful-engineer-graphic-design-innovation-and-technology-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('0509a2ca-656e-4694-adc2-92ddd128f8aa', 'Minimal Physics Atom Icon – Clean Science Symbol T-Shirt', 'This minimalist Physics design features a classic atomic structure icon paired with bold typography, representing the core foundation of science. The clean white-on-dark contrast gives it a sharp, professional appearance while maintaining universal scientific symbolism. The atomic orbit lines and central nucleus visually express balance, motion, and energy—the building blocks of the physical world. Ideal for physics students, teachers, researchers, and STEM enthusiasts, this design delivers a timeless scientific statement with modern simplicity and intellectual appeal.', 990, 'Mon Feb 16 2026 11:20:33 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:00:59 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/minimal-physics-atom-icon-clean-science-symbol-t-shirt/1771240831908-Physichh.png', 'minimal-physics-atom-icon-clean-science-symbol-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('3ca016f5-1b92-49b4-8071-e53fe6ec30f3', 'Explore the Great Outdoors – Life is an Adventure Hiking T-Shirt', 'The Explore The Great Outdoors design celebrates adventure, freedom, and the call of nature. Featuring strong vertical “EXPLORE” typography alongside a dramatic sunset forest scene and a determined hiking silhouette, this artwork captures the essence of outdoor life. The warm golden sun, soaring birds, and pine tree skyline create a bold, inspiring composition that motivates explorers to step outside and embrace the journey. Perfect for hikers, campers, trekkers, and anyone who believes life is truly an adventure.', 990, 'Sun Feb 15 2026 14:53:16 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:11:53 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Weekend ', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/explore-the-great-outdoors-life-is-an-adventure-hiking-t-shirt/1771167193877-Explore-the-world.png', 'explore-the-great-outdoors-life-is-an-adventure-hiking-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('00fb76b6-9234-42b1-a3a0-34096b2334e1', 'Vintage Film Camera Icon – Minimal Creative Cinematography T-Shirt', 'This Vintage Film Camera design captures the essence of cinematic creativity through a clean, modern graphic style. The bold dark camera silhouette symbolizes storytelling and artistic vision, while the warm circular orange element adds motion and depth, representing the endless cycle of imagination and production. Its minimalist structure gives it a timeless, professional appeal that resonates with filmmakers, videographers, editors, and visual artists. A strong yet simple statement piece for anyone passionate about film, media, and creative storytelling.', 990, 'Sun Feb 15 2026 15:29:47 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:17:13 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Old School ', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/vintage-film-camera-icon-minimal-creative-cinematography-t-shirt/1771169386265-Film-camera.png', 'vintage-film-camera-icon-minimal-creative-cinematography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('302d7e2f-e46c-4cb7-a62f-29e4cd638858', 'Film Crew Clapboard Design – Bold Cinematography T-Shirt', 'This Film Crew design captures the energy and unity of on-set professionals who bring stories to life. Inspired by a classic clapboard silhouette, the bold yellow and black color combination symbolizes action, direction, and production momentum. The clean, commanding typography makes a confident statement that highlights pride in being part of the creative backbone of filmmaking. Perfect for directors, camera operators, editors, and every dedicated crew member who works behind the scenes to make cinematic magic happen.', 990, 'Sun Feb 15 2026 15:38:30 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:18:12 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Cinewear', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/film-crew-clapboard-design-bold-cinematography-t-shirt/1771169908045-Film-Crew.png', 'film-crew-clapboard-design-bold-cinematography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('f6c2604a-42af-484a-ac71-75a2fcca58b2', 'Vintage Film Icons Design – Retro Cinema Lover Graphic T-Shirt', 'This Vintage Film Icons design is a stylish celebration of classic cinema and the art of storytelling. Featuring bold FILM lettering above four retro-inspired panels, each icon represents a core part of moviemaking—the camera that captures, the director’s chair that leads, the reel that holds the story, and the clapboard that starts the action. The warm, nostalgic color palette and textured finish give it an old-school Hollywood feel. Perfect for filmmakers, movie lovers, and cinema enthusiasts who live and breathe the magic of film.', 990, 'Sun Feb 15 2026 15:50:38 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:18:41 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Cinewear', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/vintage-film-icons-design-retro-cinema-lover-graphic-t-shirt/1771170635598-film-m.png', 'vintage-film-icons-design-retro-cinema-lover-graphic-t-shirt', 'ACTIVE');
