INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('03a170bc-cc65-4ead-9eb7-e11239209ec0', 'Feel the Music – Artistic Acoustic Guitar Splash T-Shirt', 'The Feel The Music design blends art and melody into one striking visual statement. Featuring a beautifully illustrated acoustic guitar bursting through abstract watercolor splashes, this artwork symbolizes emotion, rhythm, and creative freedom. The warm golden-orange tones contrast perfectly with cool gray and blue brush strokes, creating depth and movement that mirrors the power of music itself. Ideal for musicians, guitar lovers, and anyone who lives through sound, this design celebrates passion and artistic expression in a bold, eye-catching style.', 990, 'Sun Feb 15 2026 15:18:06 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 04:24:48 GMT+0600 (Bangladesh Standard Time)', 10, NULL, 'Melody', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/feel-the-music-artistic-acoustic-guitar-splash-t-shirt/1771168685033-Fell-the-music.png', 'feel-the-music-artistic-acoustic-guitar-splash-t-shirt', 'ACTIVE');
