INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('a4c43edd-7ad4-48e8-a614-aaa4bebd1251', 'Music on – Retro Boombox Vintage Typography T-Shirt', 'This “Music On” design brings retro sound culture to life with a detailed boombox illustration and bold, expressive typography. Inspired by classic cassette players and powerful speaker systems, the artwork captures the energy of street music, mixtapes, and nonstop rhythm. The warm vintage color scheme enhances its nostalgic appeal while keeping the design visually dynamic. Perfect for DJs, musicians, and true music enthusiasts, this design represents passion, volume, and the idea that when music is on, the world fades away.', 990, 'Mon Feb 16 2026 09:55:04 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 11:04:06 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Melody', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/music-on-retro-boombox-vintage-typography-t-shirt/1771235702789-music-on.png', 'music-on-retro-boombox-vintage-typography-t-shirt', 'ACTIVE');
