INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('246e896d-a5ca-48e6-b6ff-24f6997558c7', 'Porsche 911 Vintage Classic Muscle Car Back Part T-Shirt', 'This design celebrates the legendary Porsche 911 with a striking vintage-inspired composition. The bold top typography anchors the layout, while the detailed red classic 911 illustration captures the essence of performance, heritage, and precision engineering. Retro vertical stripes and subtle distressed textures add a timeless motorsport aesthetic, blending speed with nostalgia. Perfect for car enthusiasts, collectors, and anyone who appreciates iconic European sports car culture and classic automotive design.', 990, 'Mon Feb 16 2026 12:03:13 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 13:04:55 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Gearsift', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, 'designs/porsche-911-vintage-classic-muscle-car-back-part-t-shirt/1771243392778-Porche-911.png', NULL, 'porsche-911-vintage-classic-muscle-car-back-part-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('129c1202-ebe3-4095-ab27-e894a26dedad', 'The Music Sounds Better with You – Romantic Music Lover T-Shirt', '“The Music Sounds Better With You” is a heartfelt typography design created for those who believe that music becomes magical when shared with someone special. The clean and bold text layout keeps the message front and center, allowing the emotional meaning to shine through effortlessly. Perfect for couples, music lovers, and anyone who connects love with rhythm, this design represents harmony, companionship, and unforgettable moments created together. A simple phrase with deep emotional impact that speaks louder than sound itself.', 990, 'Mon Feb 16 2026 17:23:27 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:43:45 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Playlist', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/the-music-sounds-better-with-you-romantic-music-lover-t-shirt/1771262605919-The-music-sounds.png', 'the-music-sounds-better-with-you-romantic-music-lover-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('9fab5467-7d2d-47fe-ae11-91e89aedf3ff', 'There are No Bad Pictures – Funny Photography T-Shirt', 'This funny photography-inspired typography design is made for those who love humor behind the lens. Featuring the sarcastic quote “There Are No Bad Pictures, That’s Just How Your Face Looks Sometimes,” the layout uses bold, stacked text to highlight the punchline and enhance readability. The clean camera icon at the top reinforces the photography theme while keeping the design minimal and modern. Perfect for photographers, content creators, and anyone who enjoys playful sarcasm, this design blends humor and visual clarity into one eye-catching statement.', 990, 'Mon Feb 16 2026 17:26:14 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:44:05 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Frame It', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/there-are-no-bad-pictures-funny-photography-t-shirt/1771262771588-There-are-no-bad-.png', 'there-are-no-bad-pictures-funny-photography-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('cbc5760a-5bab-45d9-bb16-80a2d54794ba', 'This is How I Roll – Physics Diagram Funny STEM Typography T-Shirt', 'This witty STEM-inspired design blends science and humor into one brilliant visual joke. Featuring a detailed physics diagram of a rolling object on an inclined plane—complete with labeled forces like mg, Fn, friction, angular velocity, and radius—it sets up the punchline: “This Is How I Roll.” The bold typography and clean schematic style give it an authentic classroom-meets-comedy feel. Perfect for physics teachers, engineering students, STEM enthusiasts, and anyone who appreciates intelligent humor, this design turns scientific principles into a clever everyday statement.', 990, 'Mon Feb 16 2026 17:31:17 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:45:20 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/this-is-how-i-roll-physics-diagram-funny-stem-typography-t-shirt/1771263074543-this-is-how-i-roll.png', 'this-is-how-i-roll-physics-diagram-funny-stem-typography-t-shirt', 'ACTIVE');
