INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('4eba1be4-373b-4ad2-812a-efc073d6fe84', 'Trust Me I’m an Engineer – Funny Bold Engineer T-Shirt', 'This funny engineering design blends confidence with sarcasm through the bold statement “Trust Me I’m An Engineer.” The large stacked typography and subtle distressed texture give it a vintage yet powerful look that grabs attention instantly. The humor lies in the playful authority of the phrase—perfect for engineers who love showcasing their logical mindset with a touch of irony. Ideal for mechanical, civil, electrical, or software engineers, this witty typography design makes a smart, geeky, and entertaining statement wherever it’s seen.', 990, 'Mon Feb 16 2026 17:39:32 GMT+0600 (Bangladesh Standard Time)', 'Mon Feb 16 2026 17:46:29 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Engineer Hub', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/trust-me-im-an-engineer-funny-bold-engineer-t-shirt/1771263570170-trusst-mee.png', 'trust-me-im-an-engineer-funny-bold-engineer-t-shirt', 'ACTIVE');
