INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('25a074d2-db41-4fbb-987c-99c7cb7c74d8', 'Yes You Can – A Bold Reminder of Your Power Minimal T-Shirt', '“Yes You Can” is more than a motivational phrase—it is a declaration of self-belief and inner strength. By placing full emphasis on “YOU,” the design shifts the focus from doubt to confidence, reminding you that capability begins within. It represents courage in the face of challenges, persistence through obstacles, and the mindset required to move forward. This design delivers a clear, empowering message: your goals are possible, your limits can be pushed, and your success depends on your belief in yourself. Wear it as a daily affirmation of determination and unstoppable confidence.', 990, 'Tue Feb 17 2026 07:48:58 GMT+0600 (Bangladesh Standard Time)', 'Tue Feb 17 2026 10:45:12 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Rise On', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/yes-you-can-a-bold-reminder-of-your-power-minimal-t-shirt/1771314536963-Yes-you-can.png', 'yes-you-can-a-bold-reminder-of-your-power-minimal-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('6ce7e159-25c6-49cb-af56-d7ef10349163', 'YES YOU CAN – Bold Stacked Statement of Confidence T-Shirt', '“YES YOU CAN” is more than a motivational phrase—it is a direct affirmation of personal strength and possibility. The stacked presentation reinforces the message step by step, guiding the mindset from belief to action. It speaks to ambition, perseverance, and the refusal to give up. Whether facing challenges or chasing goals, this design serves as a daily reminder that capability starts within. Strong, clear, and unapologetic, it represents the confidence to move forward and the determination to succeed.', 990, 'Tue Feb 17 2026 07:57:45 GMT+0600 (Bangladesh Standard Time)', 'Tue Feb 17 2026 10:45:31 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Rise On', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/yes-you-can-bold-stacked-statement-of-confidence-t-shirt/1771315062742-Yes-you.png', 'yes-you-can-bold-stacked-statement-of-confidence-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('f2924d39-8c8b-4fe7-a250-913be89732e0', 'Play Symbol XOXO – Gamer Love Statement T-Shirt', 'This “XOXO” design reimagines a timeless expression of affection through the lens of gaming culture. By replacing the traditional letters with recognizable play symbols, it merges love and play into one powerful visual message. It represents connection, competition, and the thrill of the game, while subtly expressing devotion to the gaming lifestyle. Perfect for those who see gaming as more than a hobby—it’s identity, passion, and community. Bold yet meaningful, this design speaks directly to players who carry their love for the game everywhere they go.', 990, 'Tue Feb 17 2026 08:17:19 GMT+0600 (Bangladesh Standard Time)', 'Tue Feb 17 2026 10:45:56 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Game On', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/play-symbol-xoxo-gamer-love-statement-t-shirt/1771316237173-xoxo.png', 'play-symbol-xoxo-gamer-love-statement-t-shirt', 'ACTIVE');
