INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('9d744ec9-65a1-4925-8e88-984f8aba8759', 'Physics Formula Typography Design – Science Lover T-Shirt', 'This Physics design celebrates the beauty of equations, motion, and scientific discovery. The strong central “PHYSICS” typography is framed by iconic formulas, wave diagrams, force equations, atomic symbols, and mechanical graphics that represent core scientific principles. The white-on-black chalkboard aesthetic reinforces a classic academic vibe while maintaining a bold modern appeal. Perfect for physics enthusiasts, science students, engineers, and educators who proudly connect logic, mathematics, and curiosity into one powerful visual statement.', 990, 'Tue Feb 17 2026 07:16:30 GMT+0600 (Bangladesh Standard Time)', 'Tue Feb 17 2026 10:42:50 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Minimal', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/physics-formula-typography-design-science-lover-t-shirt/1771312588020-White-physich.png', 'physics-formula-typography-design-science-lover-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('5335c9fb-1c64-4608-9f46-89a071fddc38', 'Zero to Hero – Rise Beyond Limits Statement T-Shirt', '“Zero to Hero” is a powerful statement about personal evolution and determination. It symbolizes the mindset of starting from nothing and building something extraordinary through hard work and resilience. The phrase reflects ambition, grit, and the belief that your current position does not define your final destination. It inspires confidence in progress, celebrates growth, and encourages pushing beyond limitations. This design represents the journey of transformation—proof that with focus and perseverance, anyone can rise to greatness.', 990, 'Tue Feb 17 2026 08:28:42 GMT+0600 (Bangladesh Standard Time)', 'Tue Feb 17 2026 10:46:36 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Rise On', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/zero-to-hero-rise-beyond-limits-statement-t-shirt/1771316920792-zero-to-hero.png', 'zero-to-hero-rise-beyond-limits-statement-t-shirt', 'ACTIVE');
