INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('b57cbca0-4890-4988-a394-a83c5da3e0e9', '1994 Birthday Legend – Vintage Birthday Year T-Shirt', '“1994 Birthday Legend” is a proud statement for individuals born in a remarkable year. It represents growth, memories, and the unique identity formed by the culture and experiences of the mid-90s era. More than just a birth year, 1994 symbolizes resilience, evolution, and timeless confidence. Whether celebrating a milestone birthday or simply embracing your roots, this design stands as a badge of honor for a generation that continues to make its mark. Strong, bold, and meaningful—just like those born in 1994.', 990, 'Thu Feb 26 2026 15:06:28 GMT+0600 (Bangladesh Standard Time)', 'Thu Feb 26 2026 16:35:47 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Days', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/1994-birthday-legend-vintage-birthday-year-t-shirt/1772118386726-1994.png', '1994-birthday-legend-vintage-birthday-year-t-shirt', 'ACTIVE');
