INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('69569e06-ab8c-4b7c-b753-af941dc10d0c', 'Fun in the Sun Minimal Summer Typography Design T-Shirt', 'This design celebrates the joy of sunny days with a clean and modern aesthetic. Featuring the phrase “Fun in the Sun” alongside simple beach-inspired icons like the sun and waves, it delivers a relaxed and cheerful message. The minimal style keeps the focus on the feeling of summer—warm, easygoing, and full of good energy. Perfect for anyone who loves beach vibes, vacations, and enjoying life under the sun.', 990, 'Sun Mar 29 2026 13:48:55 GMT+0600 (Bangladesh Standard Time)', 'Tue Mar 31 2026 10:12:24 GMT+0600 (Bangladesh Standard Time)', 6, NULL, 'Weekend ', 11, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/fun-in-the-sun-minimal-summer-typography-design-t-shirt/1774792132648-Fun-in-the-sun.png', 'fun-in-the-sun-minimal-summer-typography-design-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('8f23fb8d-c26c-421d-8313-6e7262d02d76', 'বিলাই – স্টাইলিশ বাংলা ক্যাট টাইপোগ্রাফি ডিজাইন T-Shirt', 'এই ইউনিক বাংলা টাইপোগ্রাফি ডিজাইনটিতে “বিলাই” শব্দটি সৃজনশীলভাবে একটি ক্যাট ফেসের সাথে ইন্টিগ্রেট করা হয়েছে। সোনালি কালারের ব্যবহার ডিজাইনটিকে প্রিমিয়াম ও স্টাইলিশ লুক দিয়েছে, যা সহজেই নজর কাড়ে। মিনিমাল কিন্তু স্মার্ট কম্পোজিশন এটিকে আরও আকর্ষণীয় করে তোলে। যারা ক্যাট লাভার এবং ইউনিক বাংলা ডিজাইন পছন্দ করেন, তাদের জন্য এটি একটি পারফেক্ট চয়েস।', 990, 'Fri Apr 10 2026 20:52:35 GMT+0600 (Bangladesh Standard Time)', 'Sat Apr 11 2026 00:12:08 GMT+0600 (Bangladesh Standard Time)', 6, '72ccb0a6-dd4e-4a0f-aecc-9c41b8233b86', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-55/1775854354324-Bilay.png', 't-shirt-55', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('5b3b1cff-300a-4068-b608-abea7b078e52', 'বিলাই – কিউট ক্যাট লাভার বাংলা টাইপোগ্রাফি T-Shirt', 'এই ডিজাইনটি শুধু একটি বাংলা টাইপোগ্রাফি নয়, এটি প্রতিটি বিড়াল প্রেমীর অনুভূতির প্রকাশ। “বিলাই” শব্দটিকে কিউট ক্যাট ফেসের সাথে ক্রিয়েটিভভাবে মিশিয়ে এমন একটি লুক তৈরি করা হয়েছে যা একই সাথে মজার, স্টাইলিশ এবং আকর্ষণীয়। সোনালি কালারের প্রিমিয়াম ফিল ডিজাইনটিকে আরও standout করে তোলে। আপনি যদি একজন সত্যিকারের cat lover হন, তাহলে এই ডিজাইনটি আপনার personality কে প্রকাশ করার পারফেক্ট উপায়—নিজের জন্য বা প্রিয় কারো জন্য একটি দারুণ choice।', 990, 'Sat Apr 11 2026 00:36:12 GMT+0600 (Bangladesh Standard Time)', 'Sun Apr 12 2026 06:15:09 GMT+0600 (Bangladesh Standard Time)', 6, '72ccb0a6-dd4e-4a0f-aecc-9c41b8233b86', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-56/1775867771271-Bilay-white.png', 't-shirt-56', 'ACTIVE');
