INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('c5484e65-b03c-4f34-a2ad-a0e3922a7efe', 'কারে দেখাবো আমি বুকের ব্যথা তুমি যে আমার সাথী হলেনা বাংলা T-Shirt', '“কারে দেখাবো আমি বুকের ব্যথা” এই ডিজাইনটি এমন এক অনুভূতির কথা বলে, যেখানে মনের কষ্ট প্রকাশ করার মতো কেউ থাকে না। এটি সেই একাকীত্বের গল্প, যেখানে ভালোবাসার স্মৃতি ও আঘাত একসাথে হৃদয়ে জায়গা করে নেয়। প্রতিটি শব্দ যেন জমে থাকা আবেগের বহিঃপ্রকাশ, যা বলা যায় না কিন্তু অনুভব করা যায়। যারা জীবনের কোনো এক সময়ে নিজের কষ্ট লুকিয়ে রেখেছেন, তাদের জন্য এই ডিজাইনটি একদম হৃদয়ের কাছাকাছি। এটি শুধু একটি লাইন নয়, বরং এক গভীর বাস্তবতার প্রতিফলন।', 990, 'Sun Apr 12 2026 13:10:45 GMT+0600 (Bangladesh Standard Time)', 'Mon Apr 13 2026 02:00:45 GMT+0600 (Bangladesh Standard Time)', 6, 'c981bdc5-bbbb-462c-acca-dd80efe68411', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-60/1775999443892-Kare-dekhabo-ami-buker-betha_.png', 't-shirt-60', 'ACTIVE');
