INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('f0e14134-81ee-4cf0-9da9-47c7e3bdeedb', 'Life is Chess Struggle Competition Typography Chess Lover T-Shirt', '“Life is a kind of chess with struggle and competition, good and ill events” — this design delivers a powerful metaphor about life’s journey. Just like a chess game, life demands strategy, patience, and courage to face both victories and setbacks. Every move we make defines our path, and every challenge teaches us something valuable. This design speaks to individuals who understand that growth comes through competition and perseverance. It’s a reminder that both good and bad moments are part of the same game, shaping who we become over time. Perfect for those who think ahead and embrace life’s complexity.', 990, 'Sun Apr 12 2026 13:38:32 GMT+0600 (Bangladesh Standard Time)', 'Mon Apr 13 2026 02:02:00 GMT+0600 (Bangladesh Standard Time)', 6, 'd727e663-d50a-47c3-b36f-4c6675724c81', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/life-is-chess-struggle-competition-typography-chess-lover-t-shirt/1776001110158-life-is-a-kind-of-chess.png', 'life-is-chess-struggle-competition-typography-chess-lover-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('adc5256c-26a7-419a-a931-ff05120621e1', 'Looking Good Feeling Better Cat Funny T-Shirt', '“Looking Good Feeling Better” is a fun and uplifting design that blends humor with confidence. The relaxed cat illustration perfectly complements the message, symbolizing a carefree mindset and self-satisfaction. It reflects the idea that when you feel good about yourself, it naturally shows on the outside. This design is ideal for those who enjoy expressing positivity with a touch of sarcasm and humor. Whether you''re a cat lover or just someone who appreciates a good mood and style, this design makes a bold yet relatable statement about confidence and feeling great.', 990, 'Sun Apr 12 2026 13:44:21 GMT+0600 (Bangladesh Standard Time)', 'Mon Apr 13 2026 02:02:31 GMT+0600 (Bangladesh Standard Time)', 6, '72ccb0a6-dd4e-4a0f-aecc-9c41b8233b86', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/looking-good-feeling-better-cat-funny-t-shirt/1776001461089-looking-good-feling-better.png', 'looking-good-feeling-better-cat-funny-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('d64f95b7-6b0c-4e0c-aa71-173d8b2eb00f', 'Cute Cats in Pocket Funny Kawaii Cat Design T-Shirt', 'This cute cat-themed design captures the irresistible charm of multiple cats playfully gathered together in one cozy space. Each little cat adds its own personality, creating a fun and lively scene that feels both chaotic and adorable at the same time. The design represents warmth, companionship, and the simple joy that pets bring into our lives. It’s perfect for cat lovers who appreciate kawaii-style illustrations and want something that reflects their love for cute and playful moments. Whether you''re a pet enthusiast or just enjoy wholesome designs, this artwork brings a smile instantly.', 990, 'Sun Apr 12 2026 13:51:06 GMT+0600 (Bangladesh Standard Time)', 'Mon Apr 13 2026 02:02:45 GMT+0600 (Bangladesh Standard Time)', 6, '72ccb0a6-dd4e-4a0f-aecc-9c41b8233b86', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/cute-cats-in-pocket-funny-kawaii-cat-design-t-shirt/1776001864403-Lots-of-cats.png', 'cute-cats-in-pocket-funny-kawaii-cat-design-t-shirt', 'ACTIVE');
