INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('4a746607-ed15-4b9f-9abd-b63727590970', 'I’m Thinking Chess Strategy Typography Design Minimal Chess T-Shirt', 'This intelligent and minimalist chess-inspired design captures the mindset of deep strategic thinking. Featuring the phrase “I’m Thinking” above a perfectly arranged circle of chess pieces, it symbolizes focus, planning, and calculated moves. The clean monochrome style gives it a modern and premium look, making it ideal for chess enthusiasts, thinkers, and anyone who enjoys mental challenges. A bold yet subtle way to express a strategic personality.', 990, 'Sun Apr 12 2026 12:05:41 GMT+0600 (Bangladesh Standard Time)', 'Mon Apr 13 2026 01:57:17 GMT+0600 (Bangladesh Standard Time)', 6, 'd727e663-d50a-47c3-b36f-4c6675724c81', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/im-thinking-chess-strategy-typography-design-minimal-chess-t-shirt/1775995539317-Im-thinking.png', 'im-thinking-chess-strategy-typography-design-minimal-chess-t-shirt', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('33cf33e8-0873-4849-a314-8ea79f485220', 'জানতাম না প্রেম কারে বলে টাইপোগ্রাফি ডিজাইন রোমান্টিক বাংলা T-Shirt', '“জানতাম না প্রেম কারে বলে” এই ডিজাইনটি এমন এক অনুভূতির গল্প বলে, যা প্রথম ভালোবাসার অচেনা কিন্তু গভীর অভিজ্ঞতাকে সামনে আনে। এখানে প্রেম মানে শুধু অনুভূতি নয়, বরং এক নতুন দৃষ্টিভঙ্গি, যা মানুষের মন ও জীবনকে সম্পূর্ণভাবে বদলে দেয়। এই কথাগুলো আমাদের সেই সময়ের কথা মনে করিয়ে দেয়, যখন ভালোবাসা হঠাৎ করে হৃদয়ে জায়গা করে নেয় এবং সবকিছু নতুনভাবে অনুভব করায়। যারা প্রেমের সরলতা, আবেগ ও স্মৃতিকে নিজের মধ্যে ধারণ করতে চান, তাদের জন্য এই ডিজাইনটি একদম উপযুক্ত। এটি হৃদয়ের ভাষাকে প্রকাশ করার একটি সুন্দর মাধ্যম।', 990, 'Sun Apr 12 2026 12:26:54 GMT+0600 (Bangladesh Standard Time)', 'Mon Apr 13 2026 01:58:37 GMT+0600 (Bangladesh Standard Time)', 6, 'c981bdc5-bbbb-462c-acca-dd80efe68411', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/t-shirt-58/1775996812200-Jantam-na-prem-kaare_.png', 't-shirt-58', 'ACTIVE');
INSERT INTO "Product" ("id", "title", "description", "price", "createdAt", "updatedAt", "brandCommissionPct", "brandId", "brandName", "merchantCommissionPct", "mockupId", "userId", "isActive", "visibility", "backDesign", "frontDesign", "productId", "status") VALUES ('50d7984c-f3ec-4fcb-9e5c-d4c33fa934e4', 'Cute Orange Kitten Kawaii Cat Illustration Design T-Shirt', 'This charming orange kitten design captures the pure innocence and sweetness of a young cat in a visually appealing way. With its big, expressive eyes and soft features, it creates an immediate sense of warmth and affection. The design reflects the lovable nature of cats and the comfort they bring into everyday life. It’s perfect for anyone who enjoys cute, heartwarming visuals and wants to express their love for animals in a simple yet meaningful way. Whether you''re a cat enthusiast or just drawn to adorable designs, this artwork delivers a cozy and joyful feeling.', 990, 'Sun Apr 12 2026 13:55:51 GMT+0600 (Bangladesh Standard Time)', 'Mon Apr 13 2026 02:03:06 GMT+0600 (Bangladesh Standard Time)', 6, '72ccb0a6-dd4e-4a0f-aecc-9c41b8233b86', NULL, 6, 'af6bcc93-8650-4ca7-93e1-33a42a14c135', '1318a7ed-6745-4c82-aeb2-c04a4401de8c', true, true, NULL, 'designs/cute-orange-kitten-kawaii-cat-illustration-design-t-shirt/1776002148729-Lovely-cat.png', 'cute-orange-kitten-kawaii-cat-illustration-design-t-shirt', 'ACTIVE');
